import 'dart:math';

List<int> parseMusic(String musicString) {
  List<int> notes = [];

  // Parse the input string into a list of characters.
  List<String> chars = musicString.split('');

  int i = 0;
  while (i < chars.length) {
    String char = chars[i];

    if (char == '(') {
      // Skip over the parenthesis and process its contents recursively.
      int depth = 1;
      i++;
      while (depth > 0 && i < chars.length) {
        if (chars[i] == '(') depth++;
        else if (chars[i] == ')') depth--;
        i++;
      }

      if (depth == 0) {
        continue; // End of nested parentheses, skip this character.
      }
    } else if (char == '[') {
      // Process the note inside brackets as an integer value.
      int j = i + 1;
      while (j < chars.length && chars[j] != ']') {
        j++;
      }

      if (j < chars.length) {
        int value = int.parse(chars.substring(i + 1, j));
        notes.add(value);
        i = j + 1;
      } else {
        break; // Invalid format, exit loop.
      }
    } else if (char == '{') {
      // Nested structure with { ... }, ignore these for now.
      int depth = 1;
      i++;
      while (depth > 0 && i < chars.length) {
        if (chars[i] == '{') depth++;
        else if (chars[i] == '}') depth--;
        i++;
      }
    } else {
      // Regular character, add to result.
      notes.add(char.codeUnitAt(0));
      i++;
    }
  }

  return notes;
}
