List<int> parseMusic(String musicString) {
  final notes = <int>[];
  int currentNote = 0;
  int i = 0;

  while (i < musicString.length) {
    switch (musicString[i]) {
      case '(':
        // Start of a new note, add the previous one if any
        if (currentNote != 0) {
          notes.add(currentNote);
        }
        currentNote = 0;
        break;
      case ')':
        // End of the current note, add it to list and reset
        if (currentNote != 0) {
          notes.add(currentNote);
        }
        currentNote = 0;
        break;
      case '+':
        // Increase the pitch by 12 semitones (one octave)
        currentNote += 12;
        break;
      case '-':
        // Decrease the pitch by 12 semitones (one octave down)
        currentNote -= 12;
        break;
      default:
        // Convert character to MIDI note number based on ASCII value
        if (musicString[i].codeUnitAt(0) >= 33 && musicString[i].codeUnitAt(0) <= 96) {
          // Assuming characters from ! to ` represent different pitches
          currentNote = (musicString[i].codeUnitAt(0) - 33).toInt();
        } else if (musicString[i].codeUnitAt(0) >= 97 && musicString[i].codeUnitAt(0) <= 126) {
          // Characters from a-z are also used for pitches
          currentNote = (musicString[i].codeUnitAt(0) - 97 + 48).toInt(); // Adjusting to start at 48
        }
        break;
    }
    i++;
  }

  return notes;
}
