      // Handle nested parentheses
      int depth = 1;
      i++;
      String subStr = '';
      while (depth > 0 && i < musicString.length) {
        if (musicString[i] == '(') depth++;
        else if (musicString[i] == ')') depth--;
        subStr += musicString[i];
        i++;
