      // Process the substring inside the parentheses recursively
      final parsedSub = parseMusic(subStr);
      for (int note in parsedSub) {
        result.add(note);
      }
    } else if (musicString[i] == ')' || musicString[i] == ',') {
      // Skip closing parenthesis and commas
      i++;
    } else {
      // Parse number or letter
      int value = 0;
      bool isLetter = false;
      while (i < musicString.length && 
             (musicString[i].isDigit() || musicString[i] == '-' || !isLetter)) {
        if (!isLetter && musicString[i] == '-') {
          isLetter = true;
        } else {
          value = (value * 10) + int.parse(musicString[i]);
        }
        i++;
      }

      // Convert letters to numbers based on their position in alphabet
      if (isLetter) {
        value = (musicString.substring(i-2, i).toUpperCase().codeUnitAt(0) - 64) % 26;
        i--; // Correct index after parsing
      }

      result.add(value);
    }
  }

