      continue;
    } else {
      noteIndex = notes.indexOf(char);

      // Handle sharps by incrementing the index and checking bounds
      while (isSharp) {
        noteIndex++;
        if (noteIndex >= notes.length) {
          noteIndex = 0;
        }
        isSharp = false;
      }
    }
  }

