List<int> parseMusic(String musicString) {
  final List<String> notes = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];

  int currentNoteIndex = -1;
  int noteCount = 0;
  int totalNotes = 0;
  bool isSharp = false;

  for (int i = 0; i < musicString.length; i++) {
    if (musicString[i] == '(') {
      isSharp = true;
      continue;
    } else if (musicString[i] == ')') {
      isSharp = false;
      continue;
    }

    String char = musicString[i].toUpperCase();

    if (notes.contains(char)) {
      // Determine the index of the note with possible sharp or flat
      int baseIndex = notes.indexOf(char);

      // Check if there's a '#' immediately after this character
      if (i + 1 < musicString.length && musicString[i+1] == '#') {
        currentNoteIndex = baseIndex + 1;
        i += 2; // Skip the next character as it's part of the same note
      }
      // Check if there's a 'b' immediately after this character, which indicates a flat
      else if (i + 1 < musicString.length && musicString[i+1] == 'b') {
        currentNoteIndex = baseIndex > 0 ? baseIndex - 1 : 6; // Wrap around to B if needed
        i += 2; 
      }
      else {
        currentNoteIndex = baseIndex;
      }

      // Increment the count of notes
      noteCount++;
      totalNotes++;
    } else if (char == '|') {
      // End of measure marker
      if (currentNoteIndex != -1) {
        noteCount--;
        totalNotes += noteCount;
        noteCount = 0;
      }
      currentNoteIndex = -1;
    } else {
      // Invalid character encountered, skip
    }
  }

  return List.generate(totalNotes, (index) => currentNoteIndex % 7);
}
