void main() async {
  // Read input file
  final file = File('input.txt');
  final content = await file.readAsString();

  // Split into lines and process each line
  final lines = content.split('\n');
  final filteredLines = <String>[];

  for (final line in lines) {
    final parts = line.trim().split(',');
    if (parts.length >= 2 && parts[0] == 'filter') {
      final prefix = parts[1];
      final filtered = filterByPrefix(parts.skip(2).toList(), prefix);
      filteredLines.addAll(filtered);
    } else {
      filteredLines.add(line);
    }
  }

  // Write output to a new file
  final outputFile = File('output.txt');
  await outputFile.writeAsString(filteredLines.join('\n'));
}

