import 'dart:core';
import 'dart:math' show Random;

class Solution {
  List<int> unique(List<int> list) {
    // Use a set to track elements we've already added.
    final Set<int> seen = Set<int>();

    // Iterate through each element in the input list.
    for (int element in list) {
      // If the element is not in the set, add it to both the result and the set.
      if (!seen.contains(element)) {
        seen.add(element);
      }
    }

    // Convert the set back into a list and return it.
    return seen.toList();
  }
}

