  print(solution.unique([-10, -2, -1, -10, -2, 0])); // [-10, -2, -1, 0]
  print(solution.unique([]));                      // []
  print(solution.unique([1, 2, 3, 2, 1, 5]));       // [1, 2, 3, 5]

