  for (var num in [a, b]) {
    bool isPrime = true;
    for (var j = 2; j <= sqrt(num); ++j) {
      if (num % j == 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime && num > 1) primes.add(num);
  }

  return primes.length >= n ? primes[n - 1] : 0;
}

