// This function computes the nth Fibonacci number using an iterative approach.
// The function is designed to handle large values of n efficiently by avoiding recursion and stack overflow issues.

int fib4(int n) {
  // Base cases for Fibonacci sequence starting with F(0)=1 and F(1)=1
  if (n == 0 || n == 1) return 1;

  // Initialize variables representing consecutive Fibonacci numbers
  int a = 1, b = 1, c = 2;

  // Iterate from 2 up to n-1 to compute F(n)
  for (var i = 2; i < n; i++) {
    // Calculate next Fibonacci number as sum of previous two
    final d = (a + b).abs(); // Using abs() ensures non-negative result

    // Update the variables for the next iteration
    a = b;
    b = c;
    c = d;
  }

  // Return the computed value after completing iterations
  return c;
}

