import 'dart:io';

bool correctBracketing(String brackets) {
  if (brackets.isEmpty) return true;

  final List<String> stack = [];
  for (var i = 0; i < brackets.length; i++) {
    var ch = brackets[i];

    // If the character is an opening bracket, push it onto the stack
    if (ch == '(' || ch == '{' || ch == '[') {
      stack.add(ch);
    } else {
      // Check if the top of the stack matches with the closing bracket
      bool matched = false;
      switch (ch) {
        case ')':
          if (stack.isNotEmpty && stack.last == '(') {
            stack.removeLast();
            matched = true;
          }
          break;
        case '}':
          if (stack.isNotEmpty && stack.last == '{') {
            stack.removeLast();
            matched = true;
          }
          break;
        case ']':
          if (stack.isNotEmpty && stack.last == '[') {
            stack.removeLast();
            matched = true;
          }
          break;
      }

      if (!matched) {
        return false;
      }
    }
  }

  // After processing all characters, check if the stack is empty
  return stack.isEmpty;
}
