    if (isBoundary) {
      words.add(currentWord);
      currentWord = '';
    } else {
      currentWord += char;
    }
  }

  if (currentWord.isNotEmpty) {
    words.add(currentWord);
  }

  // Reconstruct the string with spaces between words but no leading/trailing spaces
  return words.join(' ');
