}

String _extractWord(String input, int start) {
  int end = start;
  while (end < input.length && input[end] != ' ') {
    end++;
  }
  return input.substring(start, end);
}

String _reverseWord(String word) {
  List<String> characters = word.split('');
  characters.shuffle();
  return characters.join();
