class Cipher {
  static const _alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

  static String encrypt(String input, [int shift = 3]) {
    if (input.isEmpty) return "";

    var result = '';
    for (var ch in input.toUpperCase().split('')) {
      if (_alphabet.contains(ch)) {
        // Find the position of the character in the alphabet
        int index = _alphabet.indexOf(ch);

        // Calculate new index with wrap-around using modulo operation
        int newIndex = (index + shift) % _alphabet.length;

        // Get encrypted char
        String encChar = _alphabet[newIndex];

        result += encChar;
      } else {
        result += ch;
      }
    }

    return result;
  }
}

