class HuffmanEncoder {
  Map<String, List<Node>> _nodesByValueMap = {};

  void addNodes(List<Node>? nodes) {
    if (nodes == null || nodes.isEmpty) return;

    var nodeSet = Set<Node>();
    var queue = Queue<Node>();

    for (var node in nodes) {
      if (!_nodesByValueMap.containsKey(node.value)) {
        _nodesByValueMap[node.value] = [node];
        queue.add(node);
      } else {
        _nodesByValueMap[node.value]?.add(node);
      }
    }

    while (!queue.isEmpty) {
      final first = queue.removeFirst(); 
      final second = queue.isNotEmpty ? queue.first : null;

      if (second != null) {
        final merged = new Node(null, first, second);

        _nodesByValueMap[merged.value] = [
          merged,
        ];

        queue.add(merged);
      }
    }
  }

  Node getRootNode() {
    if (_nodesByValueMap.entries.any((e) => e.value is Node)) {
      throw Exception("Cannot determine root node");
    }

    final entriesWithValuesOnly = _nodesByValueMap.entries.where(
      (entry) => entry.value is! Node
    );

    if (entriesWithValuesOnly.isEmpty) {
      throw Exception("No values provided");
    }

    final sortedEntries = entriesWithValuesOnly.toList()
      ..sort((a, b) => a.value.toString().compareTo(b.value.toString()));

    final rootNode = sortedEntries[0].value;

    print('Selected root node: $rootNode');

    return rootNode;
  }
}

