  for (int i = 0; i < asciiValues.length; i++) {
    // Get current character's ASCII value
    int charValue = asciiValues[i];

    // If it's not the last character, get next character's ASCII value
    int nextCharValue = i < asciiValues.length - 1 ? asciiValues[i+1] : 0;

    // Perform bitwise XOR operation between current and next character
    int xorResult = charValue ^ nextCharValue;

    // Add the result to the encodedBytes list
    encodedBytes.add(xorResult);
  }

  // Convert the encoded bytes to a base64 string
  return base64Encode(Uint8List.fromList(encodedBytes));
