  int n = arr.length;
  List<List<int>> dp = List.generate(n + 1, (_) => List.filled(n + 1, -1));

  for (int i = 0; i <= n; ++i) {
    dp[i][0] = 0;
  }

  for (int j = 0; j <= n; ++j) {
    dp[0][j] = 0;
  }

  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= n; ++j) {
