      } else {
        dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
      }
    }
  }

  String result = '';
  int index = dp[n][n];

  while (index > 0) {
    if (dp[n][index] == dp[n-1][index]) {
      result = '${arr[n-1]}$result';
      --n;
    } else {
      result = '${arr[index-1]}$result';
      --index;
    }
  }

  return [result];
