int findMax(List<int> arr, int startIdx) {
  int maxVal = arr[startIdx], maxIdx = startIdx;
  for (int j = startIdx + 1; j < arr.length; j++) {
    if (arr[j] > maxVal) {
      maxVal = arr[j];
      maxIdx = j;
    }
  }
  return maxIdx;
}

