    month = int.parse(parts[1]);
    day = int.parse(parts[2]);
  } catch (_) {
    return false;
  }

  // Check for leap year and February days
  bool isLeapYear = ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0));
  List<int> maxDays = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month > 12) return false; // Invalid month
  if (month == 2 && isLeapYear) maxDays[1] = 29;

  if (day < 1 || day > maxDays[month - 1]) return false;
  if (year < 0) return false;

  return true;
}

