bool isEqualToSumEven(int n) {
  if (n < 2 || n > 100) return false;

  int sum = n * (n + 1) ~/ 2;

  // Check if the sum is even and equal to n(n+1)/2
  if (sum % 2 != 0) return false;

  int k = sum ~/ 2;
  int a = ((-1 + sqrt(1 + 8 * k)) / 2).round();
  bool found = false;

  for (int i = 1; i <= a && !found; i++) {
    int j = k - i;
    if (j >= i && j <= n) {
      if (i * i + j * j == k * k) {
        found = true;
        break;
      }
    }
  }

  return found;
}
