String fixSpaces(String text) {
  final List<String> lines = text.split('\n');
  for (int i = 0; i < lines.length; i++) {
    String line = lines[i];
    // Trim leading and trailing spaces from the line
    line = line.trim();
    if (line.isEmpty) continue;

    int spaceCount = 0;
    bool isLeadingSpace = true;
    for (int j = 0; j < line.length && isLeadingSpace; j++) {
      if (line[j] == ' ') spaceCount++;
      else break;
    }

    int tabCount = 0;
    bool isLeadingTab = true;
    for (int j = 0; j < line.length && isLeadingTab; j++) {
      if (line[j] == '\t') tabCount++;
      else break;
    }

    int totalWhitespace = spaceCount + tabCount;

    if (totalWhitespace > 4 || totalWhitespace % 2 != 0) {
      int extra = totalWhitespace - ((totalWhitespace / 2).floor() * 2);
      int halfExtra = extra ~/ 2;
      int otherHalf = extra - halfExtra;

      if (halfExtra >= 1) {
        line = ' ' * halfExtra + line.substring(spaceCount, line.length - tabCount) + 
               ' ' * halfExtra + ' ' * otherHalf;
      } else if (otherHalf >= 1) {
        line = ' ' * halfExtra + line.substring(spaceCount, line.length - tabCount) +
               ' ' * otherHalf;
      }
    }

    lines[i] = line;
  }

  return lines.join('\n');
}
