String fixSpaces(String text) {
  if (text.isEmpty) return '';

  var result = StringBuffer();
  int i = 0;
  while (i < text.length) {
    // Skip leading spaces
    while (i < text.length && text[i] == ' ') {
      i++;
    }

    if (i >= text.length) break;

    // Check for space before punctuation or at end of line
    bool isPunctuationOrEndOfLine = false;
    if (i < text.length - 1) {
      final nextChar = text[i + 1];
      isPunctuationOrEndOfLine = 
          ['.', ',', ';', ':', '?', '!'].contains(nextChar);
    } else {
      isPunctuationOrEndOfLine = true; // End of string
    }

    if (isPunctuationOrEndOfLine || i > 0 && text[i-1] != ' ') {
      result.write(' ');
    }

    result.write(text[i]);
    i++;
  }

  return result.toString().trim();
}
