String fixSpaces(String text) {
  final List<String> lines = text.split('\n');
  for (int i = 0; i < lines.length; i++) {
    String line = lines[i];
    int spaceCount = 0;
    bool inWord = false;
    List<String> newLine = [];

    // Process each character to handle spaces and word boundaries
    for (int j = 0; j < line.length; j++) {
      if (line[j] == ' ') {
        if (!inWord) {
          // Skip the space as it's part of a sequence at start of line or between words
          continue;
        } else {
          // Add one space, but only once per group of consecutive spaces
          newLine.add(' ');
          inWord = false;
          spaceCount++;
        }
      } else {
        inWord = true;
        newLine.add(line[j]);
      }
    }

    // Handle trailing spaces by trimming them out
    while (newLine.isNotEmpty && newLine.last == ' ') {
      newLine.removeLast();
    }

    // If no characters were added, skip this line
    if (newLine.isEmpty) {
      lines[i] = '';
    } else {
      lines[i] = newLine.join('');
    }
  }

  return lines.join('\n');
}
