String fixSpaces(String text) {
  if (text == null || text.isEmpty) return text;

  int spaceCount = 0;
  List<String> result = [];

  for (int i = 0; i < text.length; i++) {
    final char = text[i];

    // Count consecutive spaces
    if (char == ' ') {
      spaceCount++;
    } else {
      // Replace multiple spaces with a single space, but not at the end
      if (spaceCount > 0 && !result.isEmpty) {
        result.add(' ');
      }
      result.add(char);
      spaceCount = 0;
    }
  }

  // Handle trailing spaces
  if (spaceCount > 0) {
    result.removeLast(); // Remove last character if it's a space
  }

  return result.join('');
}
