String fileNameCheck(String fileName) {
  if (fileName.isEmpty) {
    return "File name cannot be empty.";
  }

  // Check for invalid characters in file names.
  final forbiddenChars = ['<', '>', ':', '"', '/', '\\', '|', '?', '*'];
  for (final char in forbiddenChars) {
    if (fileName.contains(char)) {
      return "Invalid character found: $char. File names cannot contain these characters.";
    }
  }

  // Check for reserved Windows filenames and folders.
  final windowsReservedNames = [
    'CON',
    'PRN',
    'AUX',
    'COM1',
    'COM2',
    'COM3',
    'COM4',
    'COM5',
    'COM6',
    'COM7',
    'COM8',
    'COM9',
    'LPT1',
    'LPT2',
    'LPT3',
    'LPT4',
    'LPT5',
    'LPT6',
    'LPT7',
    'LPT8',
    'LPT9'
  ];

  final windowsReservedNamesLowercase = windowsReservedNames.map((name) => name.toLowerCase()).toList();

  final isWindowsReserved = windowsReservedNamesLowercase.any(
        (name) => fileName.toUpperCase().contains(name),
  );

  if (isWindowsReserved) {
    return "File name contains a Windows reserved name or folder ($fileName).";
  }

  // Check for trailing spaces at the end of the file name.
  if (fileName.trimEnd().length != fileName.length) {
    return "Trailing spaces are not allowed in file names.";
  }

  // Check that the file name does not start with a space.
  if (fileName.startsWith(' ')) {
    return "File name cannot start with a space.";
  }

  // Check that the file name does not have multiple consecutive spaces.
  if (RegExp(r' +').hasMatch(fileName)) {
    return "File name has multiple consecutive spaces.";
  }

  // Check for length limits on file names.
  if (fileName.length > 255) {
    return "File name is too long (maximum 255 characters).";
  }

  // Check if the file name starts with a dot.
  if (fileName.startsWith('.')) {
    return "File name cannot start with a dot.";
  }

  // Check if the file name ends with an extension like .exe, .dll, etc.
  if (!fileName.endsWith('.')) {
    return "File name must end with an appropriate extension such as .txt, .docx, etc.";
  } else {
    final ext = fileName.split('.').last;
    if (ext.length < 1 || ext.length > 30) {
      return "Extension should be between 1 to 30 characters long.";
    }
  }

  return "";
