// Helper function to process the sentence
String _wordsInSentence(String input) {
  // Remove any leading/trailing whitespace
  String trimmed = input.trim();

  if (trimmed.isEmpty) return '';

  List<String> tokens = [];
  int i = 0;
  while (i < trimmed.length) {
    final char = trimmed[i];

    // Check for word boundaries
    bool isWordBoundary = 
      (i == 0 || !isAlpha(trimmed[i-1])) && isAlpha(char) ||
      (i == trimmed.length - 1 || !isAlpha(trimmed[i+1])) && isAlpha(char); 

    if (isWordBoundary) {
      // Find end of current word
      int j = i + 1;
      while (j < trimmed.length && isAlpha(trimmed[j])) {
        j++;
      }

      tokens.add(trimmed.substring(i, j));
      i = j - 1; // Move past this character since we've added it as a token
    } else if (!isAlpha(char)) {
      // Add non-alphabetic characters as separate tokens
      tokens.add(char);
    }

    i++;
  }

  return tokens.join(' ');
}

