// Function to calculate the maximum number of distinct triples (a, b, c)
// such that a + b + c == n and a < b < c.
int getMaxTriples(int n) {
  if (n < 3) return 0;

  int maxTriples = 0;
  // Iterate over possible values of a starting from 1 up to n-2.
  for (int a = 1; a <= n - 2; a++) {
    // For each a, iterate over possible values of b greater than a,
    // but ensure that there's room for c which is larger than b.
    for (int b = a + 1; b <= n - 1; b++) {
      int c = n - a - b;
      // Check if c is valid (positive and greater than b).
      if (c > b && c >= 1) {
        maxTriples++;
      }
