// Calculate the maximum number of integer triples (a, b, c)
// such that a² + b² = c² and all are ≤ n.
int getMaxTriples(int n) {
  int count = 0;

  // Loop through possible values for a and b
  for (int a = 1; a < n; a++) {
    for (int b = a + 1; b < n; b++) {
      // Check if a^2 + b^2 is a perfect square
      double hypotenuseSquared = a * a + b * b;
      double hypotenuse = sqrt(hypotenuseSquared);

      // Check if it's an integer and within range
      if (hypotenuse.isInteger && hypotenuse.toInt() <= n) {
        count++;
      }
    }
  }

  return count;
}

