bool isTriangle(int x) {
  List<int> list = [];
  for (int i = 2; i < x; i++) {
    if (x % i == 0) list.add(i);
  }
  bool hasFactor = false;
  for (var factor in list) {
    if (factor != x / factor && x / factor >= 3) {
      hasFactor = true;
      break;
    }
  }
  return hasFactor;
}
