      if (hypotenuse > n) continue;

      // Check if any of the sides form a triangle with another side
      bool noTriplet = true;
      for (int k = 2; k < hypotenuse; k++) {
        if (hypotenuse % k == 0) {
          if (k != hypotenuse / k && hypotenuse / k >= 3) {
            noTriplet = false;
            break;
          }
        }
      }

      if (!noTriplet) continue;

      count++;
    }
  }
  return count;
}
