String strongestExtension(String className, List<String> extensions) {
  if (extensions.isEmpty) return '';

  final extensionScores = <String, int>{};

  for (var ext in extensions) {
    var score = 0;

    // Count the number of vowels
    final vowelCount = _countVowels(ext);
    score += vowelCount * 10; // Vowel count contributes significantly

    // Check for uppercase letters at start or end
    if (_hasUppercaseAtStartOrEnd(ext)) {
      score -= 5; // Penalize for mixed casing
    }

    // Check for special characters like !@#$%^&*()
    if (_hasSpecialCharacters(ext)) {
      score -= 2; // Slight penalty for special chars
    }

    // Prioritize longer names with more consonants
    score += ext.length - vowelCount;

    extensionScores[ext] = score;
  }

  // Find the extension with highest score and longest length as tiebreaker
  String bestExt = extensions.first;
  int maxScore = extensionScores[bestExt];

  for (var ext in extensions) {
    final currentScore = extensionScores[ext]!;
    if (currentScore > maxScore || 
        (currentScore == maxScore && ext.length > bestExt.length)) {
      bestExt = ext;
      maxScore = currentScore;
    }
  }

  return bestExt;
}

