  if (a.isEmpty || b.isEmpty) return true;

  for (int i = 0; i < b.length - patternLength + 1; i++) {
    var subStr = b.substring(i, i + patternLength);

    // Check if the substring is not in a
    if (!a.contains(subStr)) continue;

    // Check all possible rotations of the substring to see if any appear in a
    for (var rotationOffset = 1; rotationOffset < patternLength; rotationOffset++) {
